package spatial_test

import (
	"math"
	"testing"

	"github.com/Will413028/hawkr/pricebook-service/internal/domain/spatial"
	"github.com/stretchr/testify/require"
)

// Golden values generated by running Hawkr_Transformer_Pricebook@2b64d9b's
// actual _idw_at_targets (spatial/interpolation.py:423-455) against three
// planar locations at (0,0)=10, (1000,0)=30, (0,1000)=20 (meters), target
// (500,0), power=2, max_support_distance_km=50, min_supporting_neighbors=3.
func TestIDWAt_MatchesPythonReference_SymmetricCase(t *testing.T) {
	locations := []spatial.Location{
		{X: 0, Y: 0, Value: 10},
		{X: 1000, Y: 0, Value: 30},
		{X: 0, Y: 1000, Value: 20},
	}
	cfg := spatial.IDWConfig{Power: 2, MaxSupportDistanceM: 50_000, MinSupportingNeighbors: 3}
	value, neighborCount, nearestDistanceM, ok := spatial.IDWAt(500, 0, locations, cfg)
	require.True(t, ok)
	require.InDelta(t, 20.0, value, 1e-9)
	require.Equal(t, 3, neighborCount)
	require.InDelta(t, 500.0, nearestDistanceM, 1e-9)
}

func TestIDWAt_BelowMinSupportingNeighbors_ReturnsNotOK(t *testing.T) {
	// Same three locations, but max_support_distance restricted to 600m —
	// only the two nearest (each at 500m) are in range, C (1118.03m) is not,
	// so neighborCount=2 < min_supporting_neighbors=3.
	locations := []spatial.Location{
		{X: 0, Y: 0, Value: 10},
		{X: 1000, Y: 0, Value: 30},
		{X: 0, Y: 1000, Value: 20},
	}
	cfg := spatial.IDWConfig{Power: 2, MaxSupportDistanceM: 600, MinSupportingNeighbors: 3}
	_, neighborCount, _, ok := spatial.IDWAt(500, 0, locations, cfg)
	require.False(t, ok)
	require.Equal(t, 2, neighborCount)
}

func TestIDWAt_ExactMatch_ReturnsLocationValueDirectly(t *testing.T) {
	// Target coincides with location (0,0) — Python special-cases distance
	// <= 1e-6 to avoid a 1/0 division, returning the exact value. Only returns
	// ok=true if total in-range neighbor count meets MinSupportingNeighbors.
	locations := []spatial.Location{
		{X: 0, Y: 0, Value: 10},
		{X: 1000, Y: 0, Value: 30},
		{X: 0, Y: 1000, Value: 20},
	}
	cfg := spatial.IDWConfig{Power: 2, MaxSupportDistanceM: 50_000, MinSupportingNeighbors: 3}
	value, neighborCount, nearestDistanceM, ok := spatial.IDWAt(0, 0, locations, cfg)
	require.True(t, ok)
	require.InDelta(t, 10.0, value, 1e-9)
	require.Equal(t, 3, neighborCount)
	require.InDelta(t, 0.0, nearestDistanceM, 1e-9)
}

func TestIDWAt_ExactMatch_BelowMinSupportingNeighbors_ReturnsNotOK(t *testing.T) {
	// Regression test: target coincides with one location (distance <= 1e-6),
	// but total in-range neighbors (2) is below MinSupportingNeighbors (3).
	// Must return ok=false, NOT bypass the threshold check.
	locations := []spatial.Location{
		{X: 0, Y: 0, Value: 10},    // exact match at target
		{X: 1000, Y: 0, Value: 30}, // 1000m away, within 1200m max
		{X: 0, Y: 2000, Value: 20}, // 2000m away, outside 1200m max
	}
	cfg := spatial.IDWConfig{Power: 2, MaxSupportDistanceM: 1200, MinSupportingNeighbors: 3}
	_, neighborCount, _, ok := spatial.IDWAt(0, 0, locations, cfg)
	require.False(t, ok)
	require.Equal(t, 2, neighborCount)
}

func TestIDWAt_NoLocations_ReturnsNotOK(t *testing.T) {
	_, neighborCount, _, ok := spatial.IDWAt(0, 0, nil, spatial.IDWConfig{Power: 2, MaxSupportDistanceM: 1000, MinSupportingNeighbors: 1})
	require.False(t, ok)
	require.Equal(t, 0, neighborCount)
}

func TestIDWAt_ResultWithinInputRange(t *testing.T) {
	// Invariant test (not a Python parity case): IDW is a convex combination
	// of neighbor values, so the result must never fall outside [min, max]
	// of the values that actually support it.
	locations := []spatial.Location{
		{X: -3000, Y: 1500, Value: 5}, {X: 2200, Y: -900, Value: 55},
		{X: 800, Y: 3000, Value: 22}, {X: -1200, Y: -2500, Value: 40},
	}
	cfg := spatial.IDWConfig{Power: 2, MaxSupportDistanceM: 10_000, MinSupportingNeighbors: 3}
	for _, target := range [][2]float64{{0, 0}, {1000, 1000}, {-500, 500}, {300, -1200}} {
		value, _, _, ok := spatial.IDWAt(target[0], target[1], locations, cfg)
		if !ok {
			continue
		}
		require.GreaterOrEqual(t, value, 5.0-1e-9)
		require.LessOrEqual(t, value, 55.0+1e-9)
		require.False(t, math.IsNaN(value))
	}
}
